// ════════════════════════════════════════════════════════════════════════
// tools/balance-program/systems.mjs — THE SYSTEM REGISTRY OF THE BALANCE PROGRAM (data; hand-authored).
//
// One row per SYSTEM a player meets, a server runs or a ruling promises. tools/balance-program/collect.mjs
// reads every anchor from the game; this file CLAIMS them. An anchor no row claims is an ORPHAN and
// `node tools/balance-program/inventory.mjs --check` is red until a row claims it (or a row is added).
//
//   id       stable slug (phase-2 dives cite it)
//   name     the player's or the code's word for it
//   domain   the ONE phase-2 dive that owns it (DOMAINS below); never two
//   status   live      a player can reach it today (a door: a window, a client RPC, an edge verb, a section)
//            dark      built and in the tree or the database, but switched off, hidden or with no caller
//            staged    written and not applied or not merged (a staged migration, a lane, a set)
//            designed  a written spec, no build
//            ruled     Tyler said yes (or said hold), no spec
//            idea      backlog
//   code     claims CODE anchors: tested against `<kind>:<id>` (lower case), e.g. `table:clan_tavern`
//   docs     claims DOC and WORK anchors (rulings, headings, memory lines, lanes, staged files): tested
//            against the anchor's text (lower case). Also tested against the first audit to say whether
//            that audit ever named the system.
//   uses / gives   what it consumes and produces in the shared model's ledgers (01-model.md):
//            power, Level XP, skill XP, gold, items, hunt hours, town hours, stamina, server cost
//
// An anchor may be claimed by several systems (a ruling names many). A SYSTEM has exactly one domain.
// OUT_OF_SCOPE rows claim what is not a game system (team process, art and screen craft); they are
// counted and listed, never hidden, and no code anchor may fall to them except by an explicit code claim.
// ════════════════════════════════════════════════════════════════════════

export const STATUSES = Object.freeze(['live', 'dark', 'staged', 'designed', 'ruled', 'idea']);

export const DOMAINS = Object.freeze([
  { id: 'combat', name: 'Combat and progression', brief: 'hunts, the engine, Level and skills, the bar, spells, elements, fists, monsters, tiers, grounds, death, stamina' },
  { id: 'endgame', name: 'Endgame modes', brief: 'the Tower, the Catacombs, the Hearth Chest, bosses and halls, Call out, scaled hunts, the old dungeons' },
  { id: 'items', name: 'Items and crafting', brief: 'gear, loot, uniques, Tempering, jewelry, linings, salvage, Luck, every gathering and bench skill and recipe family' },
  { id: 'economy', name: 'Economy', brief: 'gold in and out, the store, the shop, the market, sinks, Tamsin, Town Works, stamina refills, Premium, Crowns' },
  { id: 'social', name: 'Social', brief: 'parties, chat, friends, the town, clans, clan castles, feasts, the castle board, factions' },
  { id: 'home', name: 'Home', brief: 'the House and every upgrade, benches, Storage, farming, curing, the training yard' },
  { id: 'retention', name: 'Retention, live ops and teaching', brief: 'first hours, what next, the wiki, the away and return moment, events, boards, the Bestiary, the long chase' },
  { id: 'platform', name: 'Platform, cost and scale', brief: 'the settle engine and tick, the envelope, accounts, access, operations, moderation, content tooling' },
]);

const S = (id, name, domain, status, code, docs, uses, gives, note = '') => ({ id, name, domain, status, code, docs, uses, gives, note });

